const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assetVersions = new Map();
function assetUrl(name) {
 if(!assetVersions.has(name)) assetVersions.set(name,crypto.createHash('sha256').update(fs.readFileSync(path.join(__dirname,'assets',name))).digest('hex').slice(0,12));
 return '/assets/'+name+'?v='+assetVersions.get(name);
}
const config = require('./assets/config.js');
const products = require('./assets/catalog.js');
const showroom = require('./content/showroom.js');
const out = path.join(__dirname, 'public');
fs.rmSync(out,{recursive:true,force:true});
fs.mkdirSync(out, {recursive:true});
fs.cpSync(path.join(__dirname,'assets'),path.join(out,'assets'),{recursive:true});
const escape = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});
const rawUrl = process.env.SITE_URL || config.siteUrl || (process.env.VERCEL_PROJECT_PRODUCTION_URL ? 'https://'+process.env.VERCEL_PROJECT_PRODUCTION_URL : process.env.VERCEL_URL ? 'https://'+process.env.VERCEL_URL : '');
let base='';
if(rawUrl) { const u=new URL(rawUrl); if(u.protocol!=='https:') throw new Error('SITE_URL must use https');base=u.origin; }
