let cardNumber=0;
function card(p) {const input='card-quantity-'+(++cardNumber);return `<article class="product-card" data-product-card data-id="${p.id}" data-category="${escape(p.category)}"><a href="/rentals/${p.id}" class="product-image"><img src="/assets/images/${p.image}" alt="${escape(p.name)} rental" loading="lazy" width="600" height="600"><span class="product-tag">${escape(p.category)}</span></a><div class="product-info"><a href="/rentals/${p.id}"><h3>${escape(p.name)}</h3></a><p class="product-tagline">${escape(p.tag)}</p><div class="product-price"><span>From <strong>${money(p.price)}</strong><small> / rental</small></span></div><p class="market-status" data-status="${p.id}">DC / NoVA · Confirm with quote</p><a class="product-details-link" href="/rentals/${p.id}">View details →</a><div class="card-quote-actions"><label for="${input}">Qty<input id="${input}" type="number" min="1" max="999" value="1" inputmode="numeric"></label><button class="button button-outline" data-add="${p.id}" data-quantity-input="${input}" aria-label="Add ${escape(p.name)} to quote">+ Add to quote</button></div></div></article>`;}
function grid(list) {return `<div class="product-grid">${list.map(card).join('')}</div>`;}
