page('/catalog','Event Rental Collection | GNS Event Rentals DC & Northern Virginia','Browse chairs, tables, linens, ceremony decor and outdoor event rentals for Washington DC and Northern Virginia. Select DFW for a Texas-specific quote.',`${intro('THE RENTAL COLLECTION','A world of <em>beautiful possibilities.</em>','A seat for every guest. A setting for every story. Find the pieces that bring your vision to life.','The collection')}<section class="wrap catalog-section"><div class="catalog-controls"><div><label for="catalog-market" class="field-label">YOUR EVENT LOCATION</label><select id="catalog-market" data-market-select class="market-select"><option value="dc">Washington, DC / Northern Virginia</option><option value="dfw">Dallas–Fort Worth, Texas</option></select></div><div class="search-box"><label class="field-label" for="catalog-search">FIND YOUR PIECES</label><input id="catalog-search" type="search" placeholder="Search chairs, tables, decor…"></div><div><label class="field-label" for="catalog-sort">SORT BY</label><select id="catalog-sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></div></div><div class="filter-tabs" role="group" aria-label="Rental categories"><button data-filter="All" aria-pressed="true">All rentals</button>${categories.map(c=>`<button data-filter="${escape(c)}" aria-pressed="false">${escape(c)}</button>`).join('')}</div><div class="catalog-meta"><span id="catalog-count">13 thoughtfully selected pieces</span><span>Starting estimates / 24-hour rental</span></div><p class="availability-note" id="availability-note">Inventory, minimums, delivery and setup vary by market. Availability is confirmed for your event date with your quote.</p><div id="catalog-grid">${grid(products)}</div><div class="empty-state" id="catalog-empty" hidden><h3>A different search might do the trick.</h3><p>Try another category or tell us what you’re looking for.</p><button class="button button-outline" id="reset-filters">Reset filters</button></div><div class="special-request">${star}<div><h3>Something special in mind?</h3><p>Tell us about your vision. We’ll discuss options for your event and location.</p></div><a href="/quote" class="button button-outline">Make a special request</a></div></section>`);
for(const p of products) page('/rentals/'+p.id,`${p.name} Rental | GNS Event Rentals`,`${p.description} Request ${p.name.toLowerCase()} rentals for Washington, DC and Northern Virginia, or choose DFW for your quote.`, `<section class="wrap product-detail">${breadcrumbs(`<a href="/catalog">The collection</a><span>/</span>${escape(p.name)}`)}<div class="detail-grid"><div class="detail-image"><img src="/assets/images/${p.image}" alt="${escape(p.name)}" width="800" height="800"><span class="eyebrow">THE GNS COLLECTION</span></div><div class="detail-copy"><p class="eyebrow">${escape(p.category)}</p><h1>${escape(p.name)}</h1><p class="detail-tagline">${escape(p.tag)}</p><p>${escape(p.description)}</p><div class="detail-price">From <strong data-detail-price="${p.id}">${money(p.price)}</strong><span>per item / 24-hour rental</span></div><label class="field-label" for="detail-market">Select your service area</label><select id="detail-market" data-market-select class="market-select"><option value="dc">Washington, DC / Northern Virginia</option><option value="dfw">Dallas–Fort Worth, Texas</option></select><p class="market-status" data-status="${p.id}">Confirm availability with your quote</p><div class="detail-actions"><label>Quantity<input type="number" id="detail-quantity" min="1" max="999" value="1" inputmode="numeric"></label><button class="button" data-add="${p.id}" data-quantity-input="detail-quantity">Add to rental list</button></div><p class="fine-print">Starting rate is an estimate. Delivery, setup and applicable taxes are quoted separately. Your rental list is a quote request, not a reservation.</p><details open><summary>The details</summary><ul>${p.details.map(d=>`<li>${escape(d)}</li>`).join('')}</ul></details><details><summary>Delivery & setup</summary><p>Tell us your venue, date and preferred service. Delivery distance, setup requirements and minimum rental values are reviewed for your selected market.</p></details></div></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">COMPLETE YOUR SETTING</p><h2>A few lovely <em>companions.</em></h2></div><a class="subtle-link" href="/catalog">Back to the collection</a></div>${grid(products.filter(x=>x.id!==p.id).slice(0,4))}</section>`);
page('/celebrations','Celebration Collections | GNS Event Rentals DC & Northern Virginia','Plan weddings, Nikkahs, showers, graduations and cultural celebrations with thoughtfully coordinated event rentals in Washington DC and Northern Virginia.',`${intro('SHOP BY CELEBRATION','A beautiful setting<br>for <em>every chapter.</em>','Start with what you’re celebrating. Find inspiration, explore pieces and tell us what would make the occasion yours.','Collections')}<section class="wrap section">${celebrationTiles()}<div class="special-request"><div><h3>Love a coordinated look?</h3><p>Explore our Gold & White collection and build your own beautiful setting.</p></div><a href="/shop-the-look" class="button">Shop the look</a></div></section>`);
page('/about','Our Story | Ben & Heavn, GNS Event Rentals','Meet Ben and Heavn, the family behind GNS Event Rentals. From family celebrations to elegant event rentals in Washington, DC and Northern Virginia.',`${intro('OUR STORY','From Our Family<br><em>Celebrations to Yours</em>','GNS Event Rentals — Ben N Heavn','Our Story')}<div class="story-masthead wrap">${photo('celebration-hero.webp','Garden reception inspiration')}<span class="inspiration-caption">Inspiration setting</span></div><article class="wrap family-story">${showroom.story.map((p,i)=>i===6?`<blockquote>${escape(p)}</blockquote>`:`<p>${i===8?escape(p).replace('GNS Event Rentals—Ben N Heavn—','<em>GNS Event Rentals—Ben N Heavn—</em>'):escape(p)}</p>`).join('')}<div class="founder-signoff"><span class="signature">Ben &amp; Heavn</span><p>Founders, GNS Event Rentals</p><p><em>From our celebrations to yours.</em></p></div><a href="/catalog" class="button">Explore our collection</a></article>`);
