page('/new-arrivals','New Arrivals | GNS Event Rentals DC & Northern Virginia','Explore pieces in the growing GNS event rental collection, from ceremony details to event essentials. Request availability for your market and date.',`${intro('NEW ARRIVALS','Just In <em>at GNS.</em>','We’re always discovering something beautiful. Explore highlights from our growing collection.','New Arrivals')}<section class="wrap section">${grid(newPieces)}<a class="subtle-link" href="/catalog">Explore all rentals →</a></section>`);
page('/gallery','Rental Gallery & Styling Inspiration | GNS Event Rentals','Explore GNS rental details and complete tablescape inspiration for weddings, Nikkahs and celebrations in Washington, DC and Northern Virginia.',`${intro('GNS GALLERY','Celebrations <em>by GNS.</em>','Explore the collection’s beautiful details and ideas for your next occasion.','Gallery')}<section class="wrap section">${galleryGrid()}<p class="collection-note">Images are rental details and styling inspiration. Inspiration settings are not presented as past client events; florals and styling are quoted separately.</p><div class="gallery-details">${selectProducts(['gold-chiavari-chair','water-goblet','cocktail-table','white-canopy']).map(p=>`<a href="/rentals/${p.id}">${photo(p.image,p.name)}<h3>${p.name}</h3></a>`).join('')}</div><div class="center-action"><a class="button" href="/quote">Bring your vision to life</a></div></section>`);
page('/rental-agreements','DMV & DFW Rental Agreements | GNS Event Rentals','Download the GNS Event Rentals agreement for your event service area. Review event details, rental items, payment terms and signatures with our team.',`${intro('PLANNING WITH CONFIDENCE','The details behind<br>your <em>beautiful celebration.</em>','Choose the agreement for your event location. GNS will complete your rental schedule and booking terms before sending your event-specific agreement for signature.','Rental Agreements')}<article class="wrap prose"><h2>Washington, DC &amp; Northern Virginia</h2><p>Our primary service area, including surrounding DMV communities and Maryland locations approved by GNS. The DMV agreement identifies the event venue jurisdiction.</p><p><a class="button" href="/assets/agreements/GNS_Event_Rentals_DMV_Rental_Agreement.pdf" download>Download DMV agreement (PDF)</a></p><h2>Dallas–Fort Worth, Texas</h2><p>Our secondary service area. The DFW agreement covers your confirmed Texas event, rental inventory and agreed services.</p><p><a class="button" href="/assets/agreements/GNS_Event_Rentals_DFW_Rental_Agreement.pdf" download>Download DFW agreement (PDF)</a></p><h2>Complete, review and sign</h2><p>Each four-page PDF has fillable fields for customer and event information, rental quantities, prices, payments, cancellation terms and signatures. Download and open it in a PDF application that supports forms, then save your completed copy.</p><p>These are blank templates. Do not sign an incomplete agreement. Your final quote, agreed fees, payment deadlines and cancellation terms must be completed and reviewed with GNS first. Ask GNS for your completed agreement if you are ready to book.</p><p>After reviewing your completed agreement, you may sign using your PDF application's signing feature or print and sign it. Return your signed copy by replying to GNS at <a href="mailto:support@gnsrental.com">support@gnsrental.com</a>. GNS will confirm the booking after the agreement and required payment are complete.</p><p><a class="button" href="/quote">Request your personalized quote</a></p></article>`);
const policies=[
 ['delivery-setup','Delivery & Setup','Support for your celebration.','Delivery and setup options are tailored to your event, venue and service area.',[['Delivery & pickup','Select delivery and pickup in your quote request. Share your venue address or city and ZIP, event date, access requirements and preferred timing.'],['Setup services','Request setup when you need additional help. Our team will review the pieces, venue requirements and services available in your market.'],['Coverage and charges','Washington, DC and Northern Virginia are our primary service area; Dallas–Fort Worth is our secondary market. Additional surrounding areas may be served depending on event size, requirements and delivery distance. Charges and minimums are confirmed in your quote.'],['Customer pickup','Customer pickup may be available depending on the products, location and scheduling. Choose that preference in your request so GNS can review the options.']]],
 ['rental-policies','Rental Policies','A clear plan for your occasion.','Your personalized quote and rental agreement confirm the terms that apply to your booking.',[['Quotes and availability','Adding pieces to a list or submitting a quote request does not reserve inventory. GNS reviews your date, service area, quantities and event requirements before confirming availability.'],['Pricing and rental duration','Website rates are starting estimates for a 24-hour rental. Delivery, setup, taxes and other applicable charges are quoted separately. Your final quote confirms pricing, rental duration and any minimum requirements.'],['Reservation and payment','Complete the applicable rental agreement and required payment to secure a reservation. GNS provides the payment schedule and booking conditions with your quote or agreement. <a href="/rental-agreements">View the DMV and DFW rental agreement templates</a>.'],['Changes, cancellation and care','Cancellation, changes, damage, loss, cleaning and return requirements are provided in the applicable quote or rental agreement. Please review them before confirming your booking.']]],
 ['terms','Terms & Conditions','Thoughtful details. Clear expectations.','Information about browsing this website and requesting rentals.',[['Using the showroom','The website helps you explore rentals, choose quantities and request a personalized quote. Submitting a request does not create a reservation or rental agreement.'],['Product information','Images may include styling inspiration or accessories that are not part of the rental item. Product descriptions identify the listed item. Availability, services and final pricing require confirmation by GNS.'],['Your rental agreement','The agreement and quote supplied for your event set the applicable booking, payment, cancellation, delivery, setup and item-care terms. Review those documents before accepting a booking.'],['Questions','Contact GNS about any website information or event requirements before making a booking. Please do not send payment card details through the quote form.']]],
 ['accessibility','Accessibility','A welcoming experience for everyone.','We want exploring the GNS collection to feel easy and welcoming.',[['Using this website','The showroom includes keyboard navigation, labeled form fields, image descriptions and a skip-to-content link. Use the search tool or category pages to find pieces and the quote form to share your event requirements.'],['Need help?','If you encounter a barrier while browsing or requesting a quote, contact GNS and describe the page, the difficulty and your preferred way to receive assistance. We’ll help you explore options for your celebration.']]]
];
for(const [slug,title,heading,copy,sections] of policies)page('/'+slug,title+' | GNS Event Rentals',copy,`${intro(title.toUpperCase(),heading,copy,title)}<article class="wrap prose">${sections.map(([title,copy])=>`<h2>${title}</h2><p>${copy}</p>`).join('')}<a class="button" href="/contact">Contact GNS</a></article>`);
page('/404','Page Not Found | GNS Event Rentals','Find your way back to the GNS Event Rentals collection.',`${intro('A LITTLE DETOUR','Let’s get back<br>to <em>something beautiful.</em>','We couldn’t find this page. Your next celebration is still waiting.')}<div class="wrap error-actions"><a href="/catalog" class="button">Explore the collection</a><a href="/" class="button button-outline">Back to home</a></div>`,{noindex:true});
const sitemap=base?`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${routes.filter(r=>!['/404','/quote'].includes(r)).map(r=>`<url><loc>${escape(base+r)}</loc></url>`).join('')}</urlset>`:'';
fs.writeFileSync(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nDisallow: /api/\n${base?`Sitemap: ${base}/sitemap.xml\n`:''}`);
if(sitemap) fs.writeFileSync(path.join(out,'sitemap.xml'),sitemap);
fs.writeFileSync(path.join(__dirname,'robots.txt'),fs.readFileSync(path.join(out,'robots.txt')));
if(sitemap)fs.writeFileSync(path.join(__dirname,'sitemap.xml'),sitemap);
else fs.rmSync(path.join(__dirname,'sitemap.xml'),{force:true});
console.log(`Built ${routes.length} pages. SEO domain: ${base||'set automatically by Vercel, or configure SITE_URL'}`);
